solucion_referencia:
class Solution:
    def countSubarrays(self, nums: list[int], minK: int, maxK: int) -> int:
        answer = length = 0
        for value in nums:
            if minK <= value <= maxK: length += 1
            else: length = 0
            answer += length
        return answer

